var n=[{title:`Vad formen förändrar`,text:`I vissa lyft kan den hängande vikten röra sig runt handleden eller underarmen, och den balanserar annorlunda än en hantel. Goblet-knäböj, marklyft och bärande använder kettlebellen på ganska enkla sätt. Clean, ryck och andra ballistiska färdigheter lägger till krav på momentum och koordination som kan vara för mycket för nybörjare.`},{title:`Börja med grunderna`,text:`Lär dig en kontrollerad höftfällning och en enkel marklyft innan du provar en sving, och gör goblet-knäböj, marklyft, rodd eller bärande före ballistiskt arbete med hög koordination. Välj en kettlebell som är tillräckligt lätt för upprepade jämna rörelser men tillräckligt tung för att utmana dig. Kön eller åldern ensam kan inte avgöra rätt startvikt. Din styrka, erfarenhet och den övning du väljer spelar roll.`},{title:`Svingens mekanik`,text:`I en vanlig tvåhandssving rör sig kettlebellen från mellan benen till ungefär brösthöjd, driven av en kraftfull höftextension och inte av att du lyfter armarna. Håll ryggraden kontrollerad, låt knäna böjas lite och styr kettlebellen längs samma båge varje gång. Gör inte övningen till en djup knäböj med en frontlyft.`},{title:`Säkerhet och progression`,text:`Öva när golvet, dina händer och området runt omkring dig är fria och torra. Lämna tillräckligt med plats framför och bakom dig för kettlebellens bana. Sluta när greppet eller din höftfällningsteknik börjar glida. Gå från marklyft och kontrollerade höftfällningar till korta set med svingar först när du kan göra rörelsen på ett pålitligt sätt.`},{title:`Så använder du TrainUp`,text:`Ange din golvyta, takhöjd och ditt underlag korrekt i Profil. Ditt program väljer bara övningar som passar ditt utrymme, ditt underlag, dina begränsningar och din koordination, vilket är viktigt för svingande rörelser i ett litet rum.`}];var r=[{label:`ACE: teknik för tvåhandssving med kettlebell`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`ACE:s övningsbibliotek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`Mayo Clinic: teknik vid styrketräning (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var l={sections:n,sources:r};export{l as default,n as sections,r as sources};